"""Self-contained local gold review. No web assets, network requests or model grading."""
import json


def render_gold_page(corpus, review):
    payload = json.dumps(dict(corpus=corpus, review=review), ensure_ascii=False).replace('<', '\\u003c')
    return PAGE.replace('PAYLOAD_JSON', payload)


PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Artint · Development gold review</title>
<style>
:root{color-scheme:light;--paper:#f7f8f5;--panel:#fff;--ink:#25382e;--muted:#526758;--line:#d6dfd5;--accent:#285447}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 system-ui,sans-serif}
header{padding:24px 32px;border-bottom:1px solid var(--line);background:var(--panel)}h1{font-size:25px;margin:0}h2{font-size:22px;line-height:1.4}h3{font-size:17px;margin:0 0 12px}p{margin:8px 0;color:var(--muted)}
.layout{display:grid;grid-template-columns:230px minmax(0,1fr);max-width:1500px;margin:auto}aside{padding:24px 16px;position:sticky;top:0;height:100vh;overflow:auto}main{padding:28px 32px;min-width:0}
button,select,input,textarea{font:inherit}button,select{cursor:pointer}button{border:1px solid var(--line);background:var(--panel);color:var(--ink);padding:9px 14px;border-radius:6px}button:hover{background:#e8eee7}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #3972ad;outline-offset:2px}
.primary{background:var(--accent);color:white}.primary:hover{background:#386b58}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:16px}input,select,textarea{padding:9px;border:1px solid var(--line);border-radius:5px;background:var(--panel);color:var(--ink)}input{max-width:300px}
.case-button{display:block;width:100%;text-align:left;margin-bottom:6px;font-size:13px}.case-button[aria-current=true]{border-color:var(--accent);background:#e1ebe1}.case-button.done::before{content:'✓ ';color:var(--accent)}
.card{padding:22px;background:var(--panel);border:1px solid var(--line);border-radius:8px;margin-bottom:18px}.notice{border-left:4px solid #9c6a22}.notice strong{display:block}.eyebrow{font-size:12px;letter-spacing:.06em;color:var(--muted);text-transform:uppercase}.meta{font-size:13px;color:var(--muted);overflow-wrap:anywhere}
.quote{border-left:3px solid #3972ad;padding-left:16px;margin:12px 0;white-space:pre-wrap;overflow-wrap:anywhere}.source-copy{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.75 system-ui;max-height:600px;overflow:auto;margin:16px 0 0;padding:16px;background:var(--paper);border-radius:4px}
mark{background:#f8e2a8;color:#352b19}details{margin:12px 0}summary{cursor:pointer;font-weight:600}textarea{width:100%;min-height:110px;resize:vertical}.json-editor{font:13px/1.6 ui-monospace,monospace;min-height:360px}label{display:block}.decision-row{display:grid;grid-template-columns:1fr 1.4fr;gap:18px}.decision-row label>span{display:block;font-size:13px;margin-bottom:5px}select{width:100%}.navigation{display:flex;justify-content:space-between;gap:12px}.error{color:#a62c2c}#status{font-weight:600}ul{padding-left:22px}
@media(max-width:760px){.layout{grid-template-columns:1fr}aside{position:static;height:auto;max-height:180px;border-bottom:1px solid var(--line)}main{padding:20px 14px}header{padding:20px 14px}.decision-row{grid-template-columns:1fr}.card{padding:16px}}
@media(prefers-color-scheme:dark){:root{color-scheme:dark;--paper:#151b17;--panel:#1c2520;--ink:#e5e9df;--muted:#a5b09c;--line:#303c32;--accent:#426d52}button:hover{background:#2b382d}.case-button[aria-current=true]{background:#293c2e}.error{color:#ffb4a8}}
</style></head><body>
<header><div class="eyebrow">Artint · evaluation authoring</div><h1>Review the proposed gold labels</h1>
<p>These are machine-proposed questions and evidence. No human approval is assumed. Nothing is sent to a server. Download partial reviews to save progress; load the saved JSON to resume.</p>
<div class="toolbar"><label>Reviewer <input id="reviewer" placeholder="Your name" autocomplete="off"></label><button id="export" class="primary">Download review JSON</button><button id="import">Load saved review</button><input id="import-file" type="file" accept="application/json" hidden><span id="status" aria-live="polite"></span></div>
<p id="message" class="meta" role="status"></p></header>
<div class="layout"><aside><h3>Questions</h3><nav id="case-list" aria-label="Review cases"></nav></aside>
<main><div class="card notice"><strong>Judge the full saved source scope</strong>
<p>A draft based on sampled anchors cannot establish that an answer is absent. Check all source copies below for proposed unanswerable questions. Validate qualifiers, amounts, dates, required facts and capture quality.</p></div>
<section class="card"><div id="case-meta" class="eyebrow"></div><h2 id="question"></h2><p id="scope-note"></p>
<h3>Proposed required facts</h3><ul id="facts"></ul><h3>Proposed evidence spans</h3><div id="evidence"></div>
<details><summary>Edit this case (question, facts, evidence, answerability)</summary><p class="meta">Keep the case ID, source scope, split and original label. Use “Revise” for changes. Evidence offsets are zero-based original-text character offsets.</p><textarea id="case-json" class="json-editor" aria-label="Editable case JSON" spellcheck="false"></textarea><button id="apply-edit">Apply case edits</button></details>
<div class="decision-row"><label><span>Your decision</span><select id="decision"><option value="pending">Pending</option><option value="accept">Accept as drafted</option><option value="revise">Accept with revisions</option><option value="exclude">Exclude with reason</option></select></label>
<label><span>Review notes / required exclusion reason</span><textarea id="notes" aria-label="Review notes"></textarea></label></div></section>
<section class="card"><h3>Full scoped source copies</h3><p>Highlighted text is proposed gold evidence. Source text is shown literally; images and links are not fetched.</p><div id="sources"></div></section>
<section class="card"><h3>Source-family review</h3><p>Related stories and syndicated copies must share a family. This map is proposed, not independently verified. If you change families, update affected case story groups using the case editor.</p>
<details><summary>Edit the proposed source-family map</summary><textarea id="family-json" class="json-editor" aria-label="Source story-family map" spellcheck="false"></textarea></details>
<label><input id="family-confirm" type="checkbox"> I checked the proposed source-family grouping and related-copy leakage.</label></section>
<div class="navigation"><button id="previous">Previous question</button><button id="next">Next question</button></div></main></div>
<script type="application/json" id="payload">PAYLOAD_JSON</script>
<script>
(()=>{'use strict';const data=JSON.parse(document.getElementById('payload').textContent),corpus=data.corpus;let review=data.review,index=0;
const $=id=>document.getElementById(id),sourceMap=new Map(corpus.sources.map(s=>[s.id,s]));
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error)}
function saveCurrent(){review.judgments[index].decision=$('decision').value;review.judgments[index].notes=$('notes').value}
function checkCase(c,original){if(!c||typeof c!=='object')throw Error('Case must be a JSON object');for(const key of ['id','source_ids','split','label'])if(JSON.stringify(c[key])!==JSON.stringify(original[key]))throw Error('Keep '+key+' unchanged');if(typeof c.question!=='string'||typeof c.story_group!=='string'||!['answerable','unanswerable'].includes(c.answerability))throw Error('Check question, story family and answerability');for(const key of ['evidence','required_facts','tags','acceptable_sets'])if(!Array.isArray(c[key]))throw Error(key+' must be an array');if(c.evidence.some(e=>!e||typeof e.quote!=='string'||typeof e.source_id!=='string')||c.required_facts.some(f=>!f||typeof f.text!=='string'))throw Error('Evidence and facts need valid text fields')}
function status(){const done=review.judgments.filter(j=>j.decision!=='pending').length;$('status').textContent=done+' / '+review.judgments.length+' decisions recorded';document.querySelectorAll('.case-button').forEach((b,i)=>b.classList.toggle('done',review.judgments[i].decision!=='pending'))}
function markedCopy(source,spans){const pre=node('div',undefined,'source-copy'),chars=Array.from(source.text);pre.dataset.sourceId=source.id;const valid=spans.filter(s=>Number.isInteger(s.start)&&Number.isInteger(s.end)&&s.start>=0&&s.end>s.start&&s.end<=chars.length).sort((a,b)=>a.start-b.start);let cursor=0;for(const span of valid){if(span.end<=cursor)continue;pre.append(document.createTextNode(chars.slice(cursor,Math.max(cursor,span.start)).join('')));pre.append(node('mark',chars.slice(Math.max(cursor,span.start),span.end).join('')));cursor=span.end}pre.append(document.createTextNode(chars.slice(cursor).join('')));return pre}
function useSelection(source,copy,alternative){try{const selection=getSelection();if(!selection.rangeCount)throw Error('Select text inside this saved source first');const range=selection.getRangeAt(0);if(!copy.contains(range.startContainer)||!copy.contains(range.endContainer))throw Error('Select text within this one source copy');const quote=range.toString();if(!quote.trim()||Array.from(quote).length>4000)throw Error('Select 1–4000 characters of evidence');const prefix=document.createRange();prefix.selectNodeContents(copy);prefix.setEnd(range.startContainer,range.startOffset);const start=Array.from(prefix.toString()).length,end=start+Array.from(quote).length;if(Array.from(source.text).slice(start,end).join('')!==quote)throw Error('Selection does not match the frozen source');saveCurrent();const c=review.judgments[index].case;if(c.evidence.some(e=>e.source_id===source.id&&e.start===start&&e.end===end))throw Error('This exact span is already listed');let number=1;while(c.evidence.some(e=>e.id==='e'+number))number++;const id='e'+number;c.evidence.push({id,source_id:source.id,text_sha256:source.text_sha256,start,end,quote});if(!c.acceptable_sets.length||alternative)c.acceptable_sets.push([id]);else c.acceptable_sets.forEach(set=>set.push(id));review.judgments[index].decision='revise';render();message('Exact source span added. Check the question, answerability, required facts and sufficient evidence sets in the case editor.')}catch(e){message(e.message,true)}}
function render(){const judgment=review.judgments[index],c=judgment.case;$('case-meta').textContent=(index+1)+' / '+review.judgments.length+' · '+c.id+' · proposed '+c.answerability;$('question').textContent=c.question;$('scope-note').textContent='Answerability applies only to these '+c.source_ids.length+' saved sources. Proposed story family: '+c.story_group;
$('facts').replaceChildren(...(c.required_facts.length?c.required_facts.map(f=>node('li',f.text)):[node('li','No required facts: proposed unanswerable; full-scope absence review is still needed.')]));
$('evidence').replaceChildren(...c.evidence.map(e=>{const wrap=node('div');wrap.append(node('div',e.source_id+' · characters '+e.start+'–'+e.end,'meta'),node('div',e.quote,'quote'));return wrap}));
$('case-json').value=JSON.stringify(c,null,2);$('decision').value=judgment.decision;$('notes').value=judgment.notes;
$('sources').replaceChildren(...c.source_ids.map(id=>{const s=sourceMap.get(id),details=node('details'),copy=markedCopy(s,c.evidence.filter(e=>e.source_id===id));const controls=node('div',undefined,'toolbar'),add=node('button','Use selected text as required evidence'),alternative=node('button','Use selected text as an alternative');add.onclick=()=>useSelection(s,copy,false);alternative.onclick=()=>useSelection(s,copy,true);controls.append(add,alternative);details.append(node('summary',s.title),node('div','Source '+id+' · captured '+s.captured_at+' · '+s.url,'meta'),copy,controls);return details}));
$('case-list').replaceChildren(...review.judgments.map((j,i)=>{const b=node('button',String(i+1).padStart(2,'0')+' · '+j.case_id,'case-button');b.setAttribute('aria-current',String(i===index));b.onclick=()=>{saveCurrent();index=i;render()};return b}));$('previous').disabled=index===0;$('next').disabled=index===review.judgments.length-1;status()}
$('decision').onchange=()=>{saveCurrent();status()};$('notes').oninput=saveCurrent;
$('apply-edit').onclick=()=>{try{const edited=JSON.parse($('case-json').value),original=corpus.cases.find(c=>c.id===review.judgments[index].case_id);checkCase(edited,original);saveCurrent();review.judgments[index].case=edited;review.judgments[index].decision='revise';render();message('Case edits retained. The CLI will validate all offsets, hashes and required fields.')}catch(e){message('Cannot apply edits: '+e.message,true)}};
$('previous').onclick=()=>{saveCurrent();if(index>0){index--;render()}};$('next').onclick=()=>{saveCurrent();if(index<review.judgments.length-1){index++;render()}};
$('export').onclick=()=>{try{saveCurrent();const families=JSON.parse($('family-json').value);if(!families||Array.isArray(families)||typeof families!=='object')throw Error('Family map must be a JSON object');review.source_story_groups=families;review.source_grouping_reviewed=$('family-confirm').checked;review.reviewer=$('reviewer').value.trim();const graded=review.judgments.some(j=>j.decision!=='pending');if(graded&&!review.reviewer)throw Error('Enter the human reviewer name before exporting decisions');review.review_kind=graded?'human':'unreviewed';review.reviewed_at=graded?new Date().toISOString():'';const url=URL.createObjectURL(new Blob([JSON.stringify(review,null,2)+'\n'],{type:'application/json'}));const a=node('a');a.href=url;a.download='gold-review.export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Downloaded review JSON. Pending decisions remain pending; the CLI creates a new corpus only after complete validation.')}catch(e){message(e.message,true)}};
$('import').onclick=()=>$('import-file').click();$('import-file').onchange=async()=>{try{const file=$('import-file').files[0];if(!file)return;if(file.size>64*1024*1024)throw Error('Review exceeds 64 MiB');const next=JSON.parse(await file.text());if(next.proposal_sha256!==data.review.proposal_sha256||!Array.isArray(next.judgments)||next.judgments.length!==corpus.cases.length)throw Error('Review belongs to another corpus');if(next.judgments.some((j,i)=>j.case_id!==data.review.judgments[i].case_id||j.case_sha256!==data.review.judgments[i].case_sha256))throw Error('Review case identity changed');next.judgments.forEach((j,i)=>checkCase(j.case,corpus.cases[i]));review=next;index=0;$('reviewer').value=review.reviewer;$('family-json').value=JSON.stringify(review.source_story_groups,null,2);$('family-confirm').checked=review.source_grouping_reviewed;render();message('Saved review loaded. The CLI performs the authoritative validation.')}catch(e){message('Cannot load review: '+e.message,true)}};
$('family-json').value=JSON.stringify(review.source_story_groups,null,2);render();})();
</script></body></html>'''
